    code: string;
    /** Hard wall-clock timeout enforced by the adapter. */
    timeoutMs: number;
    /** Supplier for the action registry the loopback bridge exposes. */
    getActions: () => Record<string, ActionEntry>;
    /** Extra bridge tool names beyond the defaults. */
